public static IneqTree TorusBalls(int count1, int count2, double R, double r)
{
    IneqTree balls = new IneqTree();
  	IneqTree notBalls = new IneqTree();

    for (int i = 0; i < count1; i++)
	for (int j = 0; j < count2; j++)      
    {
      	double fi = i * 2 * Math.PI / count1;
      	double psi = j * 2 * Math.PI / count2;
      
      	double r0 = 0.125 + 0.1 * abs(psi - PI) / PI;
      	double rr = r + (((i+j) % 2 == 0) ? -0.5 * r0 : 0.5 * r0);
      
        double x0 = (R + rr * cos(psi)) * cos(fi);
        double y0 = (R + rr * cos(psi)) * sin(fi);
      	double z0 = rr * sin(psi);      	
      
		var b = (#
            Math.Pow(Math.Abs(x - x0), 2) +
            Math.Pow(Math.Abs(y - y0), 2) +
            Math.Pow(Math.Abs(z - z0), 2) -
            Math.Pow(r0, 2));
      
      	if((i+j) % 2 == 0)
        {
			balls = balls | b;
        }
      	else
        {
			notBalls = notBalls | b;          
        }               
    }

    return ((# pow(sqrt(x * x + y * y) - R, 2)  + z * z - r * r) | balls) & !notBalls;
}

